fn main() {
    let text = String::from("hello");
    consume(text);
    // println!("{text}"); // moved value
}

fn consume(data: String) {
    println!("{data}");
}

fn main() {
    let text = String::from("hello");
    print_twice(&text);
    println!("{text}");
}

fn print_twice(data: &str) {
    println!("{data}");
    println!("{data}");
}
